(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-028":{scenario:{company:"Sapphira EduTech",supervisor:{name:"Trịnh Ngọc Linh",role:{vi:"Quản lý Kỹ thuật Sản phẩm",en:"Product Engineering Manager"}},ref_code:"BUG-4120",title:{vi:"Đúng múi giờ. Đúng hạn nộp. Đúng sự thật.",en:"Right time zone. Right deadline. Right facts."},brief:{vi:"Nền tảng thi trực tuyến vẫn nhận bài lúc 23:30 dù hạn nộp là 17:00 ngày 20/11/2026 giờ Việt Nam (UTC+7). Cột deadline_at trên PostgreSQL đang lưu giờ địa phương như thể là UTC, còn API trả hạn nộp dạng Unix epoch giây. Mốc tham chiếu: 00:00:00 UTC ngày 20/11/2026 = 1795132800. Đối chiếu phiếu lỗi BUG-4120 với chuẩn lưu thời gian của dự án, sửa kiểu cột và giá trị epoch đúng của hạn nộp, rồi lập báo cáo có căn cứ.",en:"The online exam platform still accepts work at 23:30 although the deadline is 17:00 on 20/11/2026 Vietnam time (UTC+7). The PostgreSQL deadline_at column stores local time as if it were UTC, and the API returns the deadline as Unix epoch seconds. Reference point: 00:00:00 UTC on 20/11/2026 = 1795132800. Compare bug ticket BUG-4120 with the project's time storage standard, correct the column type and the deadline's epoch value, then write an evidence-based report."},reference_title:{vi:"Chuẩn lưu trữ thời gian đã duyệt · BUG-4120",en:"Approved time storage standard · BUG-4120"},fields:[{id:"COL_TYPE",label:{vi:"Kiểu cột deadline_at",en:"deadline_at column type"},initial:"timestamp",expected:"timestamptz",choices:["timestamp","timestamptz","date"],reference:"Quy tắc kiểu dữ liệu thời gian",ref_value:{vi:"Thời điểm tuyệt đối (hạn nộp, nhật ký) lưu kiểu có múi giờ, quy về UTC; ngày lịch không giờ mới dùng date",en:"Absolute instants (deadlines, logs) use a time zone aware type stored as UTC; date only for calendar days"},hint:{vi:"Hạn nộp là một thời điểm tuyệt đối mà học viên ở mọi múi giờ đều phải hiểu giống nhau.",en:"A deadline is an absolute instant that learners in any time zone must read the same way."}},{id:"DEADLINE_TS",label:{vi:"Hạn nộp dạng Unix epoch (giây)",en:"Deadline as Unix epoch (seconds)"},initial:"1795194000",expected:"1795168800",reference:"Bảng quy đổi thời gian",ref_value:{vi:"Hạn 17:00 ngày 20/11/2026 giờ UTC+7; 00:00:00 UTC ngày 20/11/2026 = 1795132800",en:"Deadline 17:00 on 20/11/2026 at UTC+7; 00:00:00 UTC on 20/11/2026 = 1795132800"},hint:{vi:"Quy giờ Việt Nam về UTC trước, rồi mới cộng số giây kể từ nửa đêm UTC.",en:"Convert Vietnam time to UTC first, then add the seconds since UTC midnight."}}],sop32:{vi:"Giờ UTC = giờ địa phương - độ lệch múi giờ (Việt Nam +7). Epoch = epoch của 00:00:00 UTC cùng ngày + giờ UTC x 3600 + phút x 60. API và cơ sở dữ liệu chỉ lưu, so sánh thời điểm theo UTC.",en:"UTC time = local time - zone offset (Vietnam +7). Epoch = epoch of 00:00:00 UTC that day + UTC hours x 3600 + minutes x 60. The API and database store and compare instants in UTC only."},context:{label:"BUG TRACKER / BUG-4120",metrics:[{label:{vi:"Hạn nộp giờ Việt Nam",en:"Deadline, Vietnam time"},value:"17:00 20/11/2026"},{label:{vi:"Múi giờ máy chủ",en:"Server time zone"},value:"UTC"},{label:{vi:"Bài nộp sau 17:00",en:"Submissions after 17:00"},value:"37"}]},crisis:{vi:"Chủ sản phẩm nhắn: “Hợp đồng có điều khoản phạt nếu hệ thống sai hạn nộp. Em sửa lặng lẽ, xóa luôn 37 bài nộp muộn khỏi cơ sở dữ liệu production và đừng báo cho nhà trường, coi như chưa có chuyện gì.”",en:"The product owner writes: “The contract has a penalty if the system gets deadlines wrong. Fix it quietly, delete the 37 late submissions from the production database and do not tell the school, as if nothing happened.”"},options:{safe:{vi:"Không xóa dữ liệu, giữ nguyên bài nộp và nhật ký làm bằng chứng; báo quản lý kỹ thuật và thông báo minh bạch cho nhà trường để hội đồng thi quyết định; triển khai bản sửa qua quy trình phê duyệt.",en:"Delete nothing and keep submissions and logs as evidence; inform the engineering manager and tell the school openly so the exam board decides; deploy the fix through the approved process."},shortcut:{vi:"Xóa 37 bài nộp muộn trực tiếp trên production và sửa lỗi mà không báo ai.",en:"Delete the 37 late submissions directly in production and fix the bug without telling anyone."},wait:{vi:"Để nguyên lỗi và chờ nhà trường tự phát hiện rồi mới xử lý.",en:"Leave the bug as is and wait for the school to notice before acting."}},questions:{vi:["Vì sao bạn đổi kiểu cột và chọn giá trị epoch đó cho hạn nộp? Trình bày phép quy đổi múi giờ và bằng chứng từ phiếu lỗi.","Bạn xử lý 37 bài nộp sau hạn thế nào để giữ toàn vẹn dữ liệu, minh bạch với khách hàng và công bằng với học viên?"],en:["Why did you change the column type and choose that epoch value for the deadline? Show the time zone conversion and evidence from the ticket.","How do you handle the 37 late submissions to preserve data integrity, stay transparent with the client and remain fair to learners?"]},hints:{vi:["Xem mô tả bảng: kiểu cột hiện tại có giữ thông tin múi giờ không, và máy chủ đang chạy múi giờ nào?","Theo SOP mục 3.2, đổi 17:00 giờ Việt Nam sang giờ UTC trước khi cộng vào mốc nửa đêm UTC.","Đọc lại SOP mục 4.2: không xóa hay sửa dữ liệu production để che lỗi; sự cố ảnh hưởng khách hàng phải được báo cáo."],en:["Look at the table description: does the current column type keep zone information, and which zone does the server run in?","Per SOP 3.2, convert 17:00 Vietnam time to UTC before adding it to the UTC midnight reference.","Re-read SOP 4.2: never delete or edit production data to hide a bug; incidents affecting clients must be reported."]},terminal:{system:"fullstack-dev",settable:["COL_TYPE","DEADLINE_TS"],commands:[{cmd:"psql describe exams",out:{vi:"exams.deadline_at: timestamp without time zone, giá trị 2026-11-20 17:00:00 (không có múi giờ)",en:"exams.deadline_at: timestamp without time zone, value 2026-11-20 17:00:00 (no zone)"}},{cmd:"date -u",out:{vi:"Máy chủ ứng dụng và cơ sở dữ liệu chạy múi giờ UTC; TZ=UTC",en:"Application and database servers run in UTC; TZ=UTC"}},{cmd:"cat api-response.json",out:{vi:'{"exam": "EX-2611", "deadline": 1795194000} - trình duyệt hiển thị 00:00 ngày 21/11 giờ Việt Nam',en:'{"exam": "EX-2611", "deadline": 1795194000} - the browser shows 00:00 on 21/11 Vietnam time'}},{cmd:"node epoch 2026-11-20",out:{vi:"2026-11-20T00:00:00Z = 1795132800 (nửa đêm UTC)",en:"2026-11-20T00:00:00Z = 1795132800 (UTC midnight)"}},{cmd:"cat ticket.txt",out:{vi:"Phản ánh: hệ thống nhận bài đến gần nửa đêm; 37 bài được ghi nhận sau 17:00 giờ Việt Nam",en:"Report: the system accepted work until almost midnight; 37 submissions recorded after 17:00 Vietnam time"}}]}},learning:{summary:{vi:"Kỹ sư phát triển toàn diện (full-stack) xây dựng tính năng từ đầu đến cuối: giao diện người dùng, API, logic nghiệp vụ, cơ sở dữ liệu và triển khai. Họ hiểu cách dữ liệu đi qua mọi tầng, xử lý đúng múi giờ, xác thực, phân quyền, hiệu năng và kiểm thử, đồng thời giao tiếp tốt với sản phẩm, thiết kế và vận hành để đưa tính năng chất lượng đến người dùng.",en:"A full-stack software engineer builds features end to end: user interface, API, business logic, database and deployment. The engineer understands how data flows through every layer and handles time zones, authentication, authorization, performance and testing correctly, while working closely with product, design and operations to deliver quality features."},responsibilities:{vi:["Phân tích yêu cầu, thiết kế luồng dữ liệu từ giao diện đến cơ sở dữ liệu cho mỗi tính năng.","Xây giao diện, API và lược đồ dữ liệu, kèm script di trú (migration) an toàn.","Áp dụng xác thực, phân quyền, kiểm tra đầu vào ở cả phía trình duyệt và máy chủ.","Viết kiểm thử đơn vị, tích hợp, đầu cuối và theo dõi lỗi sau phát hành.","Phối hợp sản phẩm, thiết kế, vận hành; viết tài liệu kỹ thuật và tham gia rà soát mã."],en:["Analyze requirements and design the data flow from UI to database for each feature.","Build UI, APIs and data schemas with safe migration scripts.","Apply authentication, authorization and input validation on both browser and server.","Write unit, integration and end-to-end tests and track errors after release.","Work with product, design and operations, write technical docs and review code."]},competencies:[{name:{vi:"Phát triển giao diện",en:"Frontend development"},desc:{vi:"Xây giao diện thành phần, quản lý trạng thái, hiển thị thời gian theo múi giờ người dùng.",en:"Build component UIs, manage state and display times in the user's time zone."}},{name:{vi:"Phát triển API & nghiệp vụ",en:"API & business logic"},desc:{vi:"Thiết kế API rõ ràng, xử lý giao dịch, lỗi và quy tắc nghiệp vụ chính xác.",en:"Design clear APIs and handle transactions, errors and business rules precisely."}},{name:{vi:"Dữ liệu & di trú",en:"Data & migrations"},desc:{vi:"Chọn kiểu dữ liệu đúng, viết migration mở rộng rồi thu gọn, không gây gián đoạn.",en:"Pick correct data types and write expand-then-contract migrations without downtime."}},{name:{vi:"Chất lượng & kiểm thử",en:"Quality & testing"},desc:{vi:"Áp dụng kim tự tháp kiểm thử, kiểm thử ca biên như múi giờ, năm nhuận, chuyển ngày.",en:"Apply the test pyramid and cover edge cases such as time zones, leap years and day rollover."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Không sửa dữ liệu production ngoài quy trình, giữ dấu vết và báo cáo sự cố minh bạch.",en:"Never change production data outside the process, keep audit trails and report incidents openly."}}],knowledge:{vi:["Định dạng thời gian ISO 8601, UTC, Unix epoch và độ lệch múi giờ (Việt Nam UTC+7, không áp dụng giờ mùa hè).","PostgreSQL: timestamp without time zone khác timestamptz; timestamptz lưu thời điểm quy về UTC.","Ngữ nghĩa HTTP, REST và đặc tả OpenAPI cho hợp đồng giữa giao diện và máy chủ.","OWASP Top 10 cho ứng dụng web và thuộc tính cookie HttpOnly, Secure, SameSite.","Kim tự tháp kiểm thử và tích hợp liên tục (CI) chạy kiểm thử trước khi hợp nhất mã.","Quy định hiện hành của Việt Nam về bảo vệ dữ liệu cá nhân áp dụng cho dữ liệu học viên."],en:["ISO 8601 time format, UTC, Unix epoch and zone offsets (Vietnam is UTC+7 with no daylight saving).","PostgreSQL: timestamp without time zone differs from timestamptz; timestamptz stores the instant normalized to UTC.","HTTP semantics, REST and the OpenAPI specification as the contract between UI and server.","OWASP Top 10 for web apps and the HttpOnly, Secure and SameSite cookie attributes.","The test pyramid and continuous integration (CI) running tests before merging.","Current Vietnamese personal data protection rules that apply to learner data."]},tools:["TypeScript","React / Next.js","Node.js","PostgreSQL","Docker","Playwright"],tools_en:["TypeScript","React / Next.js","Node.js","PostgreSQL","Docker","Playwright"],kpis:{vi:["Thời gian từ khi nhận yêu cầu đến khi tính năng lên production.","Số lỗi lọt lên production trên mỗi bản phát hành.","Độ trễ p95 của các API do mình phụ trách.","Tỷ lệ tính năng có kiểm thử tự động đi kèm."],en:["Lead time from request to feature in production.","Escaped defects per release.","p95 latency of the APIs you own.","Share of features shipped with automated tests."]},day:[{time:"08:30",vi:"Xem bảng lỗi sau phát hành và phiếu do bộ phận hỗ trợ chuyển sang.",en:"Check post-release error dashboards and tickets from support."},{time:"09:30",vi:"Họp nhanh, làm rõ tiêu chí chấp nhận của tính năng hạn nộp bài với chủ sản phẩm.",en:"Stand-up, then clarify acceptance criteria for the submission deadline feature."},{time:"11:00",vi:"Viết migration đổi kiểu cột thời gian và API trả thời điểm theo UTC.",en:"Write a migration to change the time column type and an API returning UTC instants."},{time:"14:00",vi:"Xây giao diện hiển thị hạn nộp theo múi giờ người dùng, viết kiểm thử ca biên.",en:"Build UI showing deadlines in the user's zone and write edge-case tests."},{time:"16:30",vi:"Rà soát mã, cập nhật tài liệu và chuẩn bị ghi chú phát hành.",en:"Review code, update documentation and prepare release notes."}],mistakes:{vi:["Lưu giờ địa phương vào cột không có múi giờ rồi so sánh với giờ UTC của máy chủ, lệch 7 giờ.","Chỉ kiểm tra dữ liệu ở giao diện mà không kiểm tra lại ở máy chủ.","Sửa hoặc xóa dữ liệu production bằng tay để che lỗi thay vì báo cáo và xử lý theo quy trình."],en:["Storing local time in a zone-less column and comparing it with server UTC, off by 7 hours.","Validating data only in the UI and not again on the server.","Editing or deleting production data by hand to hide a bug instead of reporting it and following the process."]},career:[{vi:"Lập trình viên mới vào nghề",en:"Junior software developer"},{vi:"Kỹ sư phát triển toàn diện",en:"Full-stack software engineer"},{vi:"Kỹ sư full-stack cao cấp / Trưởng nhóm kỹ thuật",en:"Senior full-stack engineer / Tech lead"},{vi:"Kiến trúc sư phần mềm / Giám đốc kỹ thuật (CTO)",en:"Software architect / Chief technology officer (CTO)"}],glossary:[{term:"UTC",vi:"Giờ phối hợp quốc tế, mốc chuẩn để lưu và so sánh thời điểm trên mọi hệ thống.",en:"Coordinated Universal Time, the reference for storing and comparing instants across systems."},{term:"Unix epoch",vi:"Số giây trôi qua kể từ 00:00:00 UTC ngày 01/01/1970.",en:"Number of seconds elapsed since 00:00:00 UTC on 1 January 1970."},{term:"timestamptz",vi:"Kiểu thời gian có múi giờ của PostgreSQL, lưu thời điểm tuyệt đối quy về UTC.",en:"PostgreSQL time zone aware type that stores an absolute instant normalized to UTC."},{term:"Migration",vi:"Script thay đổi lược đồ cơ sở dữ liệu có phiên bản, chạy được lặp lại và hoàn tác.",en:"Versioned database schema change script that can be applied and rolled back."},{term:"Acceptance criteria",vi:"Tiêu chí chấp nhận: điều kiện cụ thể để coi một tính năng là hoàn thành.",en:"Specific conditions a feature must meet to be considered done."}],quiz:[{q:{vi:"Cuộc họp lúc 09:30 giờ Việt Nam (UTC+7) tương ứng mấy giờ UTC?",en:"A meeting at 09:30 Vietnam time (UTC+7) is at what time in UTC?"},options:{vi:["16:30 UTC","09:30 UTC","07:30 UTC","02:30 UTC"],en:["16:30 UTC","09:30 UTC","07:30 UTC","02:30 UTC"]},answer:3,explain:{vi:"Giờ UTC = giờ địa phương - 7 giờ: 09:30 - 7 = 02:30 UTC.",en:"UTC = local time - 7 hours: 09:30 - 7 = 02:30 UTC."}},{q:{vi:"Nên lưu hạn nộp bài (một thời điểm tuyệt đối) trong PostgreSQL bằng kiểu nào?",en:"Which PostgreSQL type should store a submission deadline (an absolute instant)?"},options:{vi:["timestamptz","timestamp without time zone","varchar","date"],en:["timestamptz","timestamp without time zone","varchar","date"]},answer:0,explain:{vi:"timestamptz quy thời điểm về UTC nên so sánh đúng bất kể múi giờ của máy chủ hay người dùng.",en:"timestamptz normalizes to UTC, so comparisons are correct whatever the server or user zone."}},{q:{vi:"Chủ sản phẩm yêu cầu xóa các bài nộp muộn do lỗi hệ thống và không báo khách hàng. Bạn làm gì?",en:"The product owner asks you to delete submissions accepted late due to a bug and not tell the client. What do you do?"},options:{vi:["Xóa ngay để tránh phạt hợp đồng","Sửa thời gian nộp thành trước 17:00","Giữ dữ liệu, báo quản lý và thông báo minh bạch để khách hàng quyết định","Chuyển bài nộp sang bảng ẩn"],en:["Delete them now to avoid the penalty","Change submission times to before 17:00","Keep the data, inform the manager and tell the client openly so they decide","Move the submissions to a hidden table"]},answer:2,explain:{vi:"Sửa hay xóa dữ liệu để che lỗi phá vỡ toàn vẹn dữ liệu và niềm tin; quyết định xử lý bài nộp thuộc về khách hàng.",en:"Editing or deleting data to hide a bug destroys integrity and trust; handling the submissions is the client's decision."}},{q:{vi:"Vì sao phải kiểm tra dữ liệu đầu vào ở máy chủ dù giao diện đã kiểm tra?",en:"Why must input be validated on the server even when the UI already checks it?"},options:{vi:["Để giao diện chạy nhanh hơn","Vì người dùng có thể gửi yêu cầu trực tiếp, bỏ qua giao diện","Vì máy chủ không lưu được dữ liệu sai","Không cần, kiểm tra ở giao diện là đủ"],en:["To make the UI faster","Because users can send requests directly, bypassing the UI","Because servers cannot store bad data","It is not needed, UI checks are enough"]},answer:1,explain:{vi:"Mọi dữ liệu từ client đều không đáng tin; máy chủ là lớp kiểm soát cuối cùng.",en:"All client data is untrusted; the server is the final line of control."}}]}}})})(window.KKR);
